package sm

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"runtime"
	"testing"
)

func loadLocalSMBIOS() (*SMTable, error) {
	table := &SMTable{}
	var err error
	table.DMI_TABLE_Bytes, err = os.ReadFile("/sys/firmware/dmi/tables/DMI")
	if err != nil {
		return nil, err
	}

	table.EPS_Bytes, err = os.ReadFile("/sys/firmware/dmi/tables/smbios_entry_point")
	if err != nil {
		return nil, err
	}
	return table, nil
}

func GetTestData(index int) *SMTable {

	mac1Table, _ := NewSMBiosDataB64(
		`X1NNXzkfAwNDAQAAAAAAAF9ETUlfezYKAPDzcyQAMw==`,
		``,
	)
	mac3Table, _ := NewSMBiosDataB64(
		`X1NNX0QfAwA7AQAAAAAAAF9ETUlfpPwJAPDviiYAMA==`,
		``,
	)

	var testData = []*SMTable{mac1Table, mac3Table}

	if runtime.GOOS == "linux" {
		var err error
		localSMBIOS, err := loadLocalSMBIOS()
		if err == nil {
			testData = append(testData, localSMBIOS)
		}
	}

	if index < 0 || index > len(testData) {
		log.Println("Test index out of range")
		return &SMTable{}
	}
	return testData[index]
}

func TestMarshal(t *testing.T) {
	data, err := loadLocalSMBIOS()
	if err != nil {
		t.Fatal(err)
	}
	err = data.LoadStructures()
	if err != nil {
		t.Fatal(err)
	}
	chunks := data.Structures[4]
	fmt.Printf("%+v\n", chunks)

	js, err := json.MarshalIndent(data, "", "   ")
	//fmt.Println(string(js))
	if err != nil {
		t.Fatal(err)
	}
	var data2 SMTable
	err = json.Unmarshal(js, &data2)
	if err != nil {
		t.Fatal(err)
	}
	chunks = data2.Structures[4]
	fmt.Printf("%+v\n", chunks)
	//fmt.Println(chunks[0].Data)
}
